package com.stayplugged.dailyca;

import com.stayplugged.dailyca.model.CaTier;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(DailyCaConfig.GROUP)
public interface DailyCaConfig extends Config
{
	String GROUP = "stayplugged-daily-ca-picker";

	@ConfigItem(
		keyName = "currentTier",
		name = "Current CA tier",
		description = "The Combat Achievement tier you are currently working at.",
		position = 0
	)
	default CaTier currentTier()
	{
		return CaTier.HARD;
	}

	@ConfigItem(
		keyName = "goalTier",
		name = "Goal CA tier",
		description = "The highest tier the daily picker may recommend.",
		position = 1
	)
	default CaTier goalTier()
	{
		return CaTier.ELITE;
	}

	@ConfigItem(
		keyName = "useBankGear",
		name = "Use bank gear",
		description = "Filter gear-sensitive tasks using the strongest gear observed when your bank was opened.",
		position = 2
	)
	default boolean useBankGear()
	{
		return true;
	}

	@ConfigItem(
		keyName = "announceInChat",
		name = "Announce daily task",
		description = "Show the daily Combat Achievement in game chat after login.",
		position = 3
	)
	default boolean announceInChat()
	{
		return true;
	}
}

package com.stayplugged.dailyca;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.stayplugged.dailyca.bank.BankGearClassifier;
import com.stayplugged.dailyca.data.CombatAchievementLibrary;
import com.stayplugged.dailyca.model.CombatAchievement;
import com.stayplugged.dailyca.model.CombatStats;
import com.stayplugged.dailyca.model.GearProfile;
import com.stayplugged.dailyca.model.PlayerProfile;
import com.stayplugged.dailyca.progress.CombatAchievementProgressReader;
import com.stayplugged.dailyca.recommendation.Recommendation;
import com.stayplugged.dailyca.recommendation.RecommendationEngine;
import com.stayplugged.dailyca.ui.DailyCaPanel;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.LinkBrowser;

@PluginDescriptor(
	name = "Daily CA Picker",
	description = "Picks one gear- and progression-aware Combat Achievement each day",
	tags = {"combat", "achievement", "ca", "daily", "pvm", "progression", "bank"}
)
public class DailyCaPlugin extends Plugin
{
	private static final String GEAR_MELEE_KEY = "observedGearMelee";
	private static final String GEAR_RANGED_KEY = "observedGearRanged";
	private static final String GEAR_MAGIC_KEY = "observedGearMagic";
	private static final String GEAR_SCANNED_KEY = "observedGearScanned";

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ConfigManager configManager;
	@Inject private DailyCaConfig config;
	@Inject private Gson gson;

	private final RecommendationEngine recommendationEngine = new RecommendationEngine();
	private final CombatAchievementProgressReader progressReader = new CombatAchievementProgressReader();
	private final BankGearClassifier gearClassifier = new BankGearClassifier();
	private final Set<Integer> bankItemIds = new HashSet<>();
	private final Set<Integer> wornItemIds = new HashSet<>();

	private CombatAchievementLibrary library;
	private DailyCaPanel panel;
	private NavigationButton navigationButton;
	private GearProfile gearProfile = emptyGearProfile();
	private boolean bankSnapshotLoaded;
	private LocalDate lastRenderedDate;
	private LocalDate lastAnnouncedDate;
	private long lastAnnouncedAccountHash = -1L;
	private long sessionGeneration;

	@Override
	protected void startUp()
	{
		library = CombatAchievementLibrary.loadBundled(gson);
		panel = new DailyCaPanel(LinkBrowser::browse,
			(task, assignmentDate, generation) -> clientThread.invoke(() ->
			{
				if (isCurrentSession(generation, sessionGeneration))
				{
					announceIfNeeded(task, assignmentDate);
				}
			}));
		navigationButton = NavigationButton.builder()
			.tooltip("Daily CA Picker")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		clientThread.invoke(this::initializeCurrentSession);
	}

	@Override
	protected void shutDown()
	{
		if (panel != null)
		{
			panel.dispose();
		}
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		navigationButton = null;
		panel = null;
		library = null;
		bankItemIds.clear();
		wornItemIds.clear();
		gearProfile = emptyGearProfile();
		bankSnapshotLoaded = false;
		lastRenderedDate = null;
		lastAnnouncedDate = null;
		lastAnnouncedAccountHash = -1L;
	}

	@Provides
	DailyCaConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(DailyCaConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (shouldClearAccountState(event.getGameState()))
		{
			resetPanelReveal();
			bankItemIds.clear();
			wornItemIds.clear();
			gearProfile = emptyGearProfile();
			bankSnapshotLoaded = false;
			lastAnnouncedDate = null;
			lastAnnouncedAccountHash = -1L;
			refresh();
			return;
		}
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		bankItemIds.clear();
		wornItemIds.clear();
		bankSnapshotLoaded = false;
		initializeCurrentSession();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		resetPanelReveal();
		bankItemIds.clear();
		wornItemIds.clear();
		gearProfile = emptyGearProfile();
		bankSnapshotLoaded = false;
		lastAnnouncedDate = null;
		lastAnnouncedAccountHash = -1L;
		initializeCurrentSession();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		LocalDate today = LocalDate.now();
		if (isNewDate(lastRenderedDate, today))
		{
			refresh();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			replaceItems(bankItemIds, event.getItemContainer());
			replaceItems(wornItemIds, client.getItemContainer(InventoryID.WORN));
			bankSnapshotLoaded = true;
			updateGearFromObservedItems(true);
		}
		else if (event.getContainerId() == InventoryID.WORN)
		{
			replaceItems(wornItemIds, event.getItemContainer());
			updateGearFromObservedItems(bankSnapshotLoaded);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (progressReader.isCompletionVarp(event.getVarpId()))
		{
			refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!DailyCaConfig.GROUP.equals(event.getGroup()) || isInternalGearKey(event.getKey()))
		{
			return;
		}
		clientThread.invoke(this::refresh);
	}

	private void initializeCurrentSession()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			refresh();
			return;
		}

		loadPersistedGear();
		replaceItems(wornItemIds, client.getItemContainer(InventoryID.WORN));
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank != null)
		{
			replaceItems(bankItemIds, bank);
			bankSnapshotLoaded = true;
		}
		updateGearFromObservedItems(bankSnapshotLoaded);
	}

	private void updateGearFromObservedItems(boolean fullBankSnapshot)
	{
		Set<Integer> allItems = new HashSet<>(bankItemIds);
		allItems.addAll(wornItemIds);
		GearProfile observed = gearClassifier.classify(allItems);
		gearProfile = mergeObservedGear(gearProfile, observed, fullBankSnapshot);
		persistGear();
		refresh();
	}

	static GearProfile mergeObservedGear(GearProfile stored, GearProfile observed, boolean fullBankSnapshot)
	{
		if (fullBankSnapshot)
		{
			return new GearProfile(observed.getMeleeTier(), observed.getRangedTier(),
				observed.getMagicTier(), true);
		}
		if (stored.isBankScanned())
		{
			return new GearProfile(
				Math.max(stored.getMeleeTier(), observed.getMeleeTier()),
				Math.max(stored.getRangedTier(), observed.getRangedTier()),
				Math.max(stored.getMagicTier(), observed.getMagicTier()),
				true);
		}
		return new GearProfile(observed.getMeleeTier(), observed.getRangedTier(),
			observed.getMagicTier(), false);
	}

	private void refresh()
	{
		if (panel == null || library == null)
		{
			return;
		}

		LocalDate today = LocalDate.now();
		lastRenderedDate = today;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			render(null, today, "Log in to read your Combat Achievement progress.");
			return;
		}

		GearProfile effectiveGear = config.useBankGear()
			? gearProfile
			: new GearProfile(4, 4, 4, true);
		CombatAchievement selected = null;
		String reason;
		if (config.useBankGear() && !effectiveGear.isBankScanned())
		{
			reason = "Open your bank once so the picker can evaluate your best available gear.";
		}
		else
		{
			Set<Integer> completed = progressReader.readCompleted(
				library.getTasks().size(), client::getVarpValue);
			PlayerProfile profile = PlayerProfile.builder()
				.currentTier(config.currentTier())
				.goalTier(config.goalTier())
				.completedTaskIds(completed)
				.gearProfile(effectiveGear)
				.combatStats(readCombatStats())
				.build();
			Recommendation recommendation = recommendationEngine.select(
				library.getTasks(), profile, today, client.getAccountHash());
			selected = recommendation.getTask();
			reason = selected == null
				? "No unfinished task matched your tier, stats, and observed gear."
				: "Selected from unfinished tasks at or below " + titleCase(config.goalTier().name())
					+ ", weighted toward your " + titleCase(config.currentTier().name()) + " progression.";
		}
		render(selected, today, reason);
	}

	private CombatStats readCombatStats()
	{
		return new CombatStats(
			client.getRealSkillLevel(Skill.ATTACK),
			client.getRealSkillLevel(Skill.STRENGTH),
			client.getRealSkillLevel(Skill.DEFENCE),
			client.getRealSkillLevel(Skill.RANGED),
			client.getRealSkillLevel(Skill.MAGIC),
			client.getRealSkillLevel(Skill.PRAYER),
			client.getRealSkillLevel(Skill.HITPOINTS));
	}

	private void render(CombatAchievement task, LocalDate today, String reason)
	{
		GearProfile shownGear = config.useBankGear() ? gearProfile : new GearProfile(4, 4, 4, true);
		long shownSessionGeneration = sessionGeneration;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.render(task, shownGear, today, reason, shownSessionGeneration);
			}
		});
	}

	private void resetPanelReveal()
	{
		sessionGeneration++;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.resetTransientState();
			}
		});
	}

	private void announceIfNeeded(CombatAchievement task, LocalDate today)
	{
		long accountHash = client.getAccountHash();
		boolean alreadyAnnounced = today.equals(lastAnnouncedDate)
			&& accountHash == lastAnnouncedAccountHash;
		if (task != null && config.announceInChat() && !alreadyAnnounced)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"Daily CA: " + task.getName() + " (" + titleCase(task.getTier().name()) + ")", null);
			lastAnnouncedDate = today;
			lastAnnouncedAccountHash = accountHash;
		}
	}

	private void persistGear()
	{
		configManager.setRSProfileConfiguration(DailyCaConfig.GROUP, GEAR_MELEE_KEY, gearProfile.getMeleeTier());
		configManager.setRSProfileConfiguration(DailyCaConfig.GROUP, GEAR_RANGED_KEY, gearProfile.getRangedTier());
		configManager.setRSProfileConfiguration(DailyCaConfig.GROUP, GEAR_MAGIC_KEY, gearProfile.getMagicTier());
		configManager.setRSProfileConfiguration(DailyCaConfig.GROUP, GEAR_SCANNED_KEY,
			gearProfile.isBankScanned());
	}

	private void loadPersistedGear()
	{
		Boolean scanned = configManager.getRSProfileConfiguration(
			DailyCaConfig.GROUP, GEAR_SCANNED_KEY, Boolean.class);
		if (!Boolean.TRUE.equals(scanned))
		{
			gearProfile = emptyGearProfile();
			return;
		}
		gearProfile = new GearProfile(
			readProfileTier(GEAR_MELEE_KEY),
			readProfileTier(GEAR_RANGED_KEY),
			readProfileTier(GEAR_MAGIC_KEY),
			true);
	}

	private int readProfileTier(String key)
	{
		Integer value = configManager.getRSProfileConfiguration(DailyCaConfig.GROUP, key, Integer.class);
		return value == null ? 0 : Math.max(0, Math.min(4, value));
	}

	static boolean shouldClearAccountState(GameState state)
	{
		return state == GameState.LOGIN_SCREEN;
	}

	static boolean isNewDate(LocalDate renderedDate, LocalDate currentDate)
	{
		return renderedDate == null || !renderedDate.equals(currentDate);
	}

	static boolean isCurrentSession(long callbackGeneration, long currentGeneration)
	{
		return callbackGeneration == currentGeneration;
	}

	private static boolean isInternalGearKey(String key)
	{
		return GEAR_MELEE_KEY.equals(key) || GEAR_RANGED_KEY.equals(key)
			|| GEAR_MAGIC_KEY.equals(key) || GEAR_SCANNED_KEY.equals(key);
	}

	private static GearProfile emptyGearProfile()
	{
		return new GearProfile(0, 0, 0, false);
	}

	private static void replaceItems(Set<Integer> target, ItemContainer container)
	{
		target.clear();
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				target.add(item.getId());
			}
		}
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(132, 96, 32));
		graphics.fillOval(1, 1, 30, 30);
		graphics.setColor(Color.WHITE);
		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
		graphics.drawString("CA", 7, 21);
		graphics.dispose();
		return image;
	}

	private static String titleCase(String value)
	{
		return value.substring(0, 1) + value.substring(1).toLowerCase();
	}
}

package com.stayplugged.dailyca.bank;

import com.stayplugged.dailyca.model.GearProfile;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

public final class BankGearClassifier
{
	public GearProfile classify(Set<Integer> itemIds)
	{
		int melee = 0;
		if (containsAny(itemIds, ItemID.ABYSSAL_WHIP, ItemID.ABYSSAL_WHIP_LAVA,
			ItemID.ABYSSAL_WHIP_ICE, ItemID.ZOMBIE_AXE))
		{
			melee = 2;
		}
		if (containsAny(itemIds, ItemID.OSMUMTENS_FANG, ItemID.OSMUMTENS_FANG_ORNAMENT,
			ItemID.BLADE_OF_SAELDOR, ItemID.BLADE_OF_SAELDOR_INACTIVE,
			ItemID.BLADE_OF_SAELDOR_INFINITE,
			ItemID.BLADE_OF_SAELDOR_INFINITE_ITHELL, ItemID.BLADE_OF_SAELDOR_INFINITE_IORWERTH,
			ItemID.BLADE_OF_SAELDOR_INFINITE_TRAHAEARN, ItemID.BLADE_OF_SAELDOR_INFINITE_CADARN,
			ItemID.BLADE_OF_SAELDOR_INFINITE_CRWYS, ItemID.BLADE_OF_SAELDOR_INFINITE_MEILYR,
			ItemID.BLADE_OF_SAELDOR_INFINITE_AMLODD))
		{
			melee = Math.max(melee, 3);
		}
		if (containsAny(itemIds, ItemID.SOULREAPER, ItemID.SOULREAPER_AXE_ORN,
			ItemID.SCYTHE_OF_VITUR, ItemID.SCYTHE_OF_VITUR_UNCHARGED,
			ItemID.SCYTHE_OF_VITUR_OR, ItemID.SCYTHE_OF_VITUR_UNCHARGED_OR,
			ItemID.SCYTHE_OF_VITUR_BL, ItemID.SCYTHE_OF_VITUR_UNCHARGED_BL))
		{
			melee = 4;
		}

		int ranged = 0;
		if (containsAny(itemIds, ItemID.TOXIC_BLOWPIPE, ItemID.TOXIC_BLOWPIPE_LOADED,
			ItemID.TOXIC_BLOWPIPE_ORNAMENT, ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT))
		{
			ranged = 3;
		}
		if (hasBowfa(itemIds))
		{
			ranged = 3;
		}
		if (itemIds.contains(ItemID.TWISTED_BOW)
			|| (hasBowfa(itemIds) && hasCrystalBody(itemIds) && hasCrystalLegs(itemIds)))
		{
			ranged = 4;
		}

		int magic = 0;
		if (containsAny(itemIds, ItemID.TOTS, ItemID.TOTS_CHARGED, ItemID.TOTS_UNCHARGED,
			ItemID.TOTS_I_CHARGED, ItemID.TOTS_I_UNCHARGED,
			ItemID.TOXIC_TOTS_CHARGED, ItemID.TOXIC_TOTS_UNCHARGED,
			ItemID.TOXIC_TOTS_I_CHARGED, ItemID.TOXIC_TOTS_I_UNCHARGED,
			ItemID.TOXIC_TOTS_CHARGED_ORN, ItemID.TOXIC_TOTS_UNCHARGED_ORN,
			ItemID.TOXIC_TOTS_I_CHARGED_ORN, ItemID.TOXIC_TOTS_I_UNCHARGED_ORN,
			ItemID.TOTS_CHARGED_ORN, ItemID.TOTS_UNCHARGED_ORN, ItemID.TOTS_ORN,
			ItemID.TOTS_I_CHARGED_ORN, ItemID.TOTS_I_UNCHARGED_ORN))
		{
			magic = 2;
		}
		if (containsAny(itemIds, ItemID.SANGUINESTI_STAFF, ItemID.SANGUINESTI_STAFF_UNCHARGED,
			ItemID.SANGUINESTI_STAFF_OR, ItemID.SANGUINESTI_STAFF_UNCHARGED_OR))
		{
			magic = 3;
		}
		if (containsAny(itemIds, ItemID.TUMEKENS_SHADOW, ItemID.TUMEKENS_SHADOW_UNCHARGED))
		{
			magic = 4;
		}

		return new GearProfile(melee, ranged, magic, true);
	}

	private static boolean hasBowfa(Set<Integer> itemIds)
	{
		return containsAny(itemIds, ItemID.BOW_OF_FAERDHINEN, ItemID.BOW_OF_FAERDHINEN_INACTIVE,
			ItemID.BOW_OF_FAERDHINEN_INFINITE,
			ItemID.BOW_OF_FAERDHINEN_INFINITE_ITHELL, ItemID.BOW_OF_FAERDHINEN_INFINITE_IORWERTH,
			ItemID.BOW_OF_FAERDHINEN_INFINITE_TRAHAEARN, ItemID.BOW_OF_FAERDHINEN_INFINITE_CADARN,
			ItemID.BOW_OF_FAERDHINEN_INFINITE_CRWYS, ItemID.BOW_OF_FAERDHINEN_INFINITE_MEILYR,
			ItemID.BOW_OF_FAERDHINEN_INFINITE_AMLODD);
	}

	private static boolean hasCrystalBody(Set<Integer> itemIds)
	{
		return containsAny(itemIds, ItemID.CRYSTAL_CHESTPLATE, ItemID.CRYSTAL_CHESTPLATE_INACTIVE,
			ItemID.CRYSTAL_CHESTPLATE_HEFIN, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_HEFIN,
			ItemID.CRYSTAL_CHESTPLATE_ITHELL, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_ITHELL,
			ItemID.CRYSTAL_CHESTPLATE_IORWERTH, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_IORWERTH,
			ItemID.CRYSTAL_CHESTPLATE_TRAHAEARN, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_TRAHAEARN,
			ItemID.CRYSTAL_CHESTPLATE_CADARN, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_CADARN,
			ItemID.CRYSTAL_CHESTPLATE_CRWYS, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_CRWYS,
			ItemID.CRYSTAL_CHESTPLATE_AMLODD, ItemID.CRYSTAL_CHESTPLATE_INACTIVE_AMLODD);
	}

	private static boolean hasCrystalLegs(Set<Integer> itemIds)
	{
		return containsAny(itemIds, ItemID.CRYSTAL_PLATELEGS, ItemID.CRYSTAL_PLATELEGS_INACTIVE,
			ItemID.CRYSTAL_PLATELEGS_HEFIN, ItemID.CRYSTAL_PLATELEGS_INACTIVE_HEFIN,
			ItemID.CRYSTAL_PLATELEGS_ITHELL, ItemID.CRYSTAL_PLATELEGS_INACTIVE_ITHELL,
			ItemID.CRYSTAL_PLATELEGS_IORWERTH, ItemID.CRYSTAL_PLATELEGS_INACTIVE_IORWERTH,
			ItemID.CRYSTAL_PLATELEGS_TRAHAEARN, ItemID.CRYSTAL_PLATELEGS_INACTIVE_TRAHAEARN,
			ItemID.CRYSTAL_PLATELEGS_CADARN, ItemID.CRYSTAL_PLATELEGS_INACTIVE_CADARN,
			ItemID.CRYSTAL_PLATELEGS_CRWYS, ItemID.CRYSTAL_PLATELEGS_INACTIVE_CRWYS,
			ItemID.CRYSTAL_PLATELEGS_AMLODD, ItemID.CRYSTAL_PLATELEGS_INACTIVE_AMLODD);
	}

	private static boolean containsAny(Set<Integer> itemIds, int... candidates)
	{
		for (int candidate : candidates)
		{
			if (itemIds.contains(candidate))
			{
				return true;
			}
		}
		return false;
	}
}

package com.stayplugged.dailyca.data;

import com.google.gson.Gson;
import com.stayplugged.dailyca.model.CaTier;
import com.stayplugged.dailyca.model.CombatAchievement;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class CombatAchievementLibrary
{
	private static final String RESOURCE = "/com/stayplugged/dailyca/combat_achievements.json";
	private final List<CombatAchievement> tasks;

	private CombatAchievementLibrary(List<CombatAchievement> tasks)
	{
		this.tasks = Collections.unmodifiableList(new ArrayList<>(tasks));
	}

	public static CombatAchievementLibrary loadBundled(Gson gson)
	{
		try (InputStream stream = CombatAchievementLibrary.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				throw new IllegalStateException("Missing bundled Combat Achievement catalog");
			}
			return load(new InputStreamReader(stream, StandardCharsets.UTF_8), gson);
		}
		catch (Exception ex)
		{
			throw catalogError(ex);
		}
	}

	static CombatAchievementLibrary load(Reader reader, Gson gson)
	{
		try
		{
			CatalogDto catalog = gson.fromJson(reader, CatalogDto.class);
			if (catalog == null || catalog.tasks == null || catalog.taskCount == null
				|| catalog.taskCount != catalog.tasks.size() || catalog.tasks.isEmpty())
			{
				throw new IllegalArgumentException("Catalog count or task list is invalid");
			}

			List<CombatAchievement> tasks = new ArrayList<>(catalog.tasks.size());
			for (int index = 0; index < catalog.tasks.size(); index++)
			{
				TaskDto task = catalog.tasks.get(index);
				if (task == null || task.id != index)
				{
					throw new IllegalArgumentException("Task IDs must be contiguous from zero");
				}
				requireText(task.name, "name", index);
				requireText(task.tier, "tier", index);
				requireText(task.monster, "monster", index);
				requireText(task.type, "type", index);
				requireText(task.description, "description", index);
				requireText(task.wikiUrl, "wikiUrl", index);
				if (!isAllowedWikiUrl(task.wikiUrl))
				{
					throw new IllegalArgumentException("Task " + index + " has an untrusted Wiki URL");
				}
				tasks.add(new CombatAchievement(task.id, task.name,
					CaTier.valueOf(task.tier.toUpperCase()), task.monster, task.type,
					task.description, task.wikiUrl));
			}
			return new CombatAchievementLibrary(tasks);
		}
		catch (Exception ex)
		{
			throw catalogError(ex);
		}
	}

	public List<CombatAchievement> getTasks()
	{
		return tasks;
	}

	public CombatAchievement findById(int id)
	{
		return id >= 0 && id < tasks.size() ? tasks.get(id) : null;
	}

	private static void requireText(String value, String field, int taskId)
	{
		if (value == null || value.trim().isEmpty())
		{
			throw new IllegalArgumentException("Task " + taskId + " is missing " + field);
		}
	}

	private static boolean isAllowedWikiUrl(String value)
	{
		try
		{
			URI uri = new URI(value);
			return "https".equalsIgnoreCase(uri.getScheme())
				&& "oldschool.runescape.wiki".equalsIgnoreCase(uri.getHost())
				&& uri.getUserInfo() == null
				&& (uri.getPort() == -1 || uri.getPort() == 443)
				&& uri.getPath() != null
				&& uri.getPath().startsWith("/w/");
		}
		catch (URISyntaxException | NullPointerException ex)
		{
			return false;
		}
	}

	private static IllegalStateException catalogError(Exception cause)
	{
		return cause instanceof IllegalStateException
			? (IllegalStateException) cause
			: new IllegalStateException("Unable to load Combat Achievement catalog", cause);
	}

	private static final class CatalogDto
	{
		private Integer taskCount;
		private List<TaskDto> tasks;
	}

	private static final class TaskDto
	{
		private int id;
		private String name;
		private String tier;
		private String monster;
		private String type;
		private String description;
		private String wikiUrl;
	}
}

